يطة","en":"Map display"},"text_bcda4a955df7":{"fr":"Tout","ar":"الكل","en":"All"},"text_c7d44d72fa47":{"fr":"Agences","ar":"الوكالات","en":"Agencies"},"text_d08e01417571":{"fr":"Lignes","ar":"الخطوط","en":"Routes"},"text_74c28f96ba0d":{"fr":"Liaisons géographiques indicatives : elles ne représentent pas les routes routières. Seules les agences avec coordonnées sont localisées.","ar":"روابط جغرافية تقريبية لا تمثل المسارات الطرقية. تظهر فقط الوكالات ذات الإحداثيات.","en":"Indicative geographic connections, not road itineraries. Only agencies with coordinates are mapped."},"text_c9e34c310b35":{"fr":"Les trajets disponibles","ar":"الخطوط المتاحة","en":"Available routes"},"text_e0fd3c8b26e5":{"fr":"lignes","ar":"خطوط","en":"routes"},"text_f1c90bceffe5":{"fr":"Localiser cette ligne","ar":"عرض الخط على الخريطة","en":"Locate this route"},"text_4e0534017cae":{"fr":"Aucun trajet correspondant","ar":"لا توجد رحلة مطابقة","en":"No matching journeys"},"text_80f102fc3c61":{"fr":"Modifiez les villes, la date ou la classe, ou contactez notre équipe.","ar":"غيروا المدن أو التاريخ أو الفئة أو تواصلوا مع فريقنا.","en":"Change the cities, date or class, or contact our team."},"text_35d5f8e60822":{"fr":"Afficher plus de lignes","ar":"عرض المزيد من الخطوط","en":"Show more routes"},"text_277f2e31ace1":{"fr":"Nos agences","ar":"وكالاتنا","en":"Our agencies"},"text_6f4bb3e25693":{"fr":"Filtrer par ville","ar":"تصفية حسب المدينة","en":"Filter by city"},"text_f139c54b7dd6":{"fr":"Toutes les agences","ar":"جميع الوكالات","en":"All agencies"},"text_8baf531b9ade":{"fr":"Voir sur la carte","ar":"عرض على الخريطة","en":"View on map"},"text_0aa81762192d":{"fr":"Voir toutes les agences","ar":"عرض جميع الوكالات","en":"View all agencies"}}'::jsonb || coalesce(content->'copy','{}'::jsonb)) where slug='lignes' and exists(select 1 from jsonb_object_keys('{"text_a692bb103ab3":{"fr":"Le réseau","ar":"الشبكة","en":"The network"},"text_57cce3ffe3ad":{"fr":"Votre prochaine destination","ar":"وجهتكم القادمة","