update public.site_pages set content=jsonb_set(content,'{copy}','{"text_95fa6b27692b":{"fr":"Déposez votre colis","ar":"أودعوا أمانتكم","en":"Drop off your parcel"},"text_7395bee98942":{"fr":"Présentez le colis au guichet Irsaliyat. Nous le pesons, l''enregistrons et vous remettons un numéro de suivi.","ar":"قدموا الأمانة في شباك إرساليات. نقوم بوزنها وتسجيلها ومنحكم رقم تتبع.","en":"Bring the parcel to the Irsaliyat counter. We weigh it, register it and issue a tracking number."},"text_95d3c8989f13":{"fr":"Voyage avec l''autocar","ar":"السفر مع الحافلة","en":"Travels with the coach"},"text_8b2bd40ceaac":{"fr":"Il est placé dans un compartiment fermé dédié, séparé des bagages classiques.","ar":"توضع في صندوق مغلق مخصص، منفصل عن الأمتعة العادية.","en":"It travels in a dedicated sealed compartment, separate from regular luggage."},"text_73b6e216b4a5":{"fr":"Arrivée en agence","ar":"الوصول إلى الوكالة","en":"Arrival at the agency"},"text_5d0898e0194c":{"fr":"Le destinataire reçoit une alerte SMS ou WhatsApp dès l''arrivée.","ar":"يتلقى المرسل إليه تنبيهاً عبر SMS أو واتساب عند الوصول.","en":"The recipient receives an SMS or WhatsApp alert on arrival."},"text_f6b950d5e567":{"fr":"Remise sécurisée","ar":"تسليم آمن","en":"Secure handover"},"text_60a162e1535d":{"fr":"Vérification de la pièce d''identité et du code secret avant la remise.","ar":"التحقق من بطاقة التعريف والرمز السري قبل التسليم.","en":"ID and secret code are checked before handover."},"text_cf04082cac0b":{"fr":"Irsaliyat · messagerie express","ar":"إرساليات · توصيل سريع","en":"Irsaliyat · express parcels"},"text_e6fa5ed22794":{"fr":"Vos colis, livrés vite et en toute confiance","ar":"أمانتكم تصل بسرعة، بأمان ووضوح","en":"Your parcels, delivered fast and safely"},"text_59adb8f9eb01":{"fr":"Notre réseau de colis utilise les mêmes liaisons quotidiennes que nos autocars, avec un suivi direct sur WhatsApp.","ar":"شبكة التوصيل الخاصة بنا تستعمل نفس رحلات الحافلات اليومية بين المدن، مع تتبع مباشر عبر واتساب.","en":"Our parcel network uses the same daily intercity coach routes, with direct WhatsApp tracking."},"text_df01d4b731c3":{"fr":"Comment ça marche","ar":"كيف تعمل الخدمة","en":"How it works"},"text_555d59a0bd73":{"fr":"Du dépôt à la remise en quatre étapes","ar":"من الإيداع إلى التسليم في أربع خطوات","en":"From drop-off to delivery in four steps"},"text_fb30ae8c285e":{"fr":"Tarifs","ar":"الأسعار","en":"Pricing"},"text_53c01dacd291":{"fr":"Des tarifs clairs selon le poids","ar":"أسعار واضحة حسب الوزن","en":"Clear pricing by weight"},"text_edf6cf5d9204":{"fr":"Tarifs de base par catégorie. Des suppléments peuvent s''appliquer selon la destination ou la nature du colis.","ar":"الأسعار الأساسية لكل فئة. قد تُضاف رسوم حسب الوجهة أو طبيعة الأمانة.","en":"Base fares per category. Surcharges may apply depending on destination or parcel type."},"text_49e333f4f39c":{"fr":"Demander pour votre destination","ar":"اسأل عن وجهتكم","en":"Ask about your destination"},"text_fd45ba571a87":{"fr":"tarif de base","ar":"سعر أساسي","en":"base fare"},"text_bdbce9febab4":{"fr":"Suivi et sécurisé","ar":"تتبع وتسليم مؤمن","en":"Tracked and secured"},"text_b310ecd98789":{"fr":"Aucun tarif publié","ar":"لا توجد أسعار منشورة","en":"No parcel rates"},"text_dd9085ae6490":{"fr":"Contactez notre équipe pour connaître le tarif de votre envoi.","ar":"تواصلوا مع فريقنا لمعرفة أسعار إرسالياتكم.","en":"Contact our team for a quote for your parcel."},"text_9f38ae8098e2":{"fr":"Nous contacter","ar":"اتصلوا بنا","en":"Contact us"},"text_feecc2f902e8":{"fr":"Pour les commerçants","ar":"للتجار","en":"For retailers"},"text_0239e9bb3b61":{"fr":"Paiement à la livraison, reversé chaque semaine","ar":"خدمة الدفع عند الاستلام","en":"Cash on delivery, reconciled weekly"},"text_94b51582a43e":{"fr":"Expédiez vos produits avec nous. Nous encaissons à la livraison et vous reversons chaque semaine avec un récapitulatif.","ar":"انقلوا منتجاتكم معنا، ونحن نحصل على المبلغ عند التسليم ونحوّله لكم أسبوعياً مع كشف مفصل.","en":"Ship your products with us. We collect payment on delivery and pay you weekly with a detailed statement."},"text_20e3ebeead0f":{"fr":"Paiement à la livraison","ar":"الدفع عند التسليم","en":"Cash on delivery"},"text_e4d0b543a685":{"fr":"Reversement hebdomadaire","ar":"تحويل أسبوعي","en":"Weekly payout"},"text_7ae43de7089d":{"fr":"Colis traçables","ar":"أمانات قابلة للتتبع","en":"Trackable parcels"},"text_2b34a2619a8b":{"fr":"Compartiment sécurisé","ar":"صندوق مؤمن","en":"Secured compartment"},"text_dddf86c53ff6":{"fr":"Parler à l''équipe Irsaliyat","ar":"تواصل مع فريق إرساليات","en":"Talk to the Irsaliyat team"},"text_15936a24b63a":{"fr":"Suivre votre colis","ar":"تتبع أمانتكم","en":"Track your parcel"},"text_2b27304a563b":{"fr":"Numéro de suivi","ar":"رقم التتبع","en":"Tracking number"},"text_8555a9966ded":{"fr":"Suivre sur WhatsApp","ar":"تتبع عبر واتساب","en":"Track on WhatsApp"},"text_f8970bd401c6":{"fr":"Le suivi est momentanément indisponible. Contactez une agence.","ar":"خدمة التتبع غير متاحة حالياً. تواصلوا مع الوكالة.","en":"Tracking is currently unavailable. Please contact an agency."},"text_c120f11bb031":{"fr":"Veuillez saisir votre numéro de suivi.","ar":"يرجى إدخال رقم التتبع.","en":"Please enter your tracking number."},"text_4218a4cc0da9":{"fr":"Saisissez le numéro remis au dépôt. L''équipe Irsaliyat vous répond directement.","ar":"أدخل الرقم الذي تلقيتموه عند الإيداع. فريق إرساليات يجيبكم مباشرة.","en":"Enter the number issued at drop-off. Our Irsaliyat team replies directly."},"text_194d63493fa7":{"fr":"Notre réseau de messagerie","ar":"شبكة إرسالياتنا","en":"Our parcel network"},"text_e35b49703650":{"fr":"Découvrez les villes et agences desservies par notre service de livraison de colis et d''envois.","ar":"اكتشفوا المدن والوكالات التي تغطيها خدمة إرسال الطرود لدينا.","en":"Discover the cities and agencies served by our parcel delivery service."},"text_0b7897cb8ec3":{"fr":"Les informations du réseau sont momentanément indisponibles.","ar":"معلومات الشبكة 