 an SMS or WhatsApp alert on arrival."},"text_f6b950d5e567":{"fr":"Remise sécurisée","ar":"تسليم آمن","en":"Secure handover"},"text_60a162e1535d":{"fr":"Vérification de la pièce d''identité et du code secret avant la remise.","ar":"التحقق من بطاقة التعريف والرمز السري قبل التسليم.","en":"ID and secret code are checked before handover."},"text_cf04082cac0b":{"fr":"Irsaliyat · messagerie express","ar":"إرساليات · توصيل سريع","en":"Irsaliyat · express parcels"},"text_e6fa5ed22794":{"fr":"Vos colis, livrés vite et en toute confiance","ar":"أمانتكم تصل بسرعة، بأمان ووضوح","en":"Your parcels, delivered fast and safely"},"text_59adb8f9eb01":{"fr":"Notre réseau de colis utilise les mêmes liaisons quotidiennes que nos autocars, avec un suivi direct sur WhatsApp.","ar":"شبكة التوصيل الخاصة بنا تستعمل نفس رحلات الحافلات اليومية بين المدن، مع تتبع مباشر عبر واتساب.","en":"Our parcel network uses the same daily intercity coach routes, with direct WhatsApp tracking."},"text_df01d4b731c3":{"fr":"Comment ça marche","ar":"كيف تعمل الخدمة","en":"How it works"},"text_555d59a0bd73":{"fr":"Du dépôt à la remise en quatre étapes","ar":"من الإيداع إلى التسليم في أربع خطوات","en":"From drop-off to delivery in four steps"},"text_fb30ae8c285e":{"fr":"Tarifs","ar":"الأسعار","en":"Pricing"},"text_53c01dacd291":{"fr":"Des tarifs clairs selon le poids","ar":"أسعار واضحة حسب الوزن","en":"Clear pricing by weight"},"text_edf6cf5d9204":{"fr":"Tarifs de base par catégorie. Des suppléments peuvent s''appliquer selon la destination ou la nature du colis.","ar":"الأسعار الأساسية لكل فئة. قد تُضاف رسوم حسب الوجهة أو طبيعة الأمانة.","en":"Base fares per category. Surcharges may apply depending on destination or parcel type."},"text_49e333f4f39c":{"fr":"Demander pour votre destination","ar":"اسأل عن وجهتكم","en":"Ask about your destination"},"text_fd45ba571a87":{"fr":"tarif de base","ar":"سعر أساسي","en":"base fare"},"text_bdbce9febab4":{"fr":"Suivi et sécurisé","ar":"تتبع وتسليم مؤمن","en":"Tracked and secured"},"text_b310ecd98789":{"fr":"Aucun tarif publié","ar":"لا توجد أسعار منشورة","en":"No parcel rates"},"text_dd9085ae6490":{"fr":"Contactez notre équipe pour connaître le tarif de votre envoi.","ar":"تواصلوا مع فريقنا لمعرفة أسعار إرسالياتكم.","en":"Contact our team for a quote for your parcel."},"text_9f38ae8098e2":{"fr":"Nous contacter","ar":"اتصلوا بنا","en":"Contact us"},"text_feecc2f902e8":{"fr":"Pour les commerçants","ar":"للتجار","en":"For retailers"},"text_0239e9bb3b61":{"fr":"Paiement à la livraison, reversé chaque semaine","ar":"خدمة الدفع عند الاستلام","en":"Cash on delivery, reconciled weekly"},"text_94b51582a43e":{"fr":"Expédiez vos produits avec nous. Nous encaissons à la livraison et vous reversons chaque semaine avec un récapitulatif.","ar":"انقلوا منتجاتكم معنا، ونحن نحصل على المبلغ عند التسليم ونحوّله لكم أسبوعياً مع كشف مفصل.","en":"Ship your products with us. We collect payment on delivery and pay you weekly with a detailed statement."},"text_20e3ebeead0f":{"fr":"Paiement à la livraison","ar":"الدفع عند التسليم","en":"Cash on delivery"},"text_e4d0b543a685":{"fr":"Reversement hebdomadaire","ar":"تحويل أسبوعي","en":"Weekly payout"},"text_7ae43de7089d":{"fr":"Colis traçables","ar":"أمانات قابلة للتتبع","en":"Trackable parcels"},"text_2b34a2619a8b":{"fr":"Compartiment sécurisé","ar":"صندوق مؤمن","en":"Secured compartment"},"text_dddf86c53ff6":{"fr":"Parler à l''équipe Irsaliyat","ar":"تواصل مع فريق إرساليات","en":"Talk to the Irsaliyat team"},"text_15936a24b63a":{"fr":"Suivre votre colis","ar":"تتبع أمانتكم","en":"Track your parcel"},"text_2b27304a563b":{"fr":"Numéro de suivi","ar":"رقم التتبع","en":"Tracking number"},"text_8555a9966ded":{"fr":"Suivre sur WhatsApp","ar":"تتبع عبر واتساب","en":"Track on WhatsApp"},"text_f8970bd401c6":{"fr":"Le suivi est momentanément indisponible. Contactez une agence.","ar":"خدمة التتبع غير متاحة حالياً. تواصلوا مع الوكالة.","en":"Tracking is currently unavailable. Please contact an agency."},"text_c120f11bb031":{"fr":"Veuillez saisir votre numéro de suivi.","ar":"يرجى إدخال رقم التتبع.","en":"Please enter your tracking number."},"text_4218a4cc0da9":{"fr":"Saisissez le numéro remis au dépôt. L''équipe Irsaliyat vous répond directement.","ar":"أدخل الرقم الذي تلقيتموه عند الإيداع. فريق إرساليات يجيبكم مباشرة.","en":"Enter the number issued at drop-off. Our Irsaliyat team replies directly."},"text_194d63493fa7":{"fr":"Notre réseau de messagerie","ar":"شبكة إرسالياتنا","en":"Our parcel network"},"text_e35b49703650":{"fr":"Découvrez les villes et agences desservies par notre service de livraison de colis et d''envois.","ar":"اكتشفوا المدن والوكالات التي تغطيها خدمة إرسال الطرود لدينا.","en":"Discover the cities and agencies served by our parcel delivery service."},"text_0b7897cb8ec3":{"fr":"Les informations du réseau sont momentanément indisponibles.","ar":"معلومات الشبكة غير متاحة حالياً.","en":"Network information is temporarily unavailable."},"text_b7f5ef931116":{"fr":"La carte du réseau sera prochainement disponible.","ar":"ستتوفر خريطة الشبكة قريباً.","en":"The network map will be available soon."},"text_621061dc7a98":{"fr":"Villes desservies","ar":"المدن المخدومة","en":"Served cities"},"text_6f13f83e5a9b":{"fr":"Nos agences de messagerie","ar":"وكالات إرسالياتنا","en":"Our parcel agencies"},"text_6f4bb3e25693":{"fr":"Filtrer par ville","ar":"تصفية حسب المدينة","en":"Filter by city"},"text_e92207923058":{"fr":"Toutes les villes","ar":"جميع المدن","en":"All cities"},"text_e98461de52c3":{"fr":"Les coordonnées des agences de messagerie seront publiées prochainement.","ar":"ستنشر بيانات وكالات الإرساليات قريباً.","en":"Parcel agency contact details will be published soon."}}'::jsonb) k where not coalesce(content->'copy','{}'::jsonb) ? k);
update public.site_pages set content=jsonb_set(content,'{links}','{"link_e0c7bc0426f0":"/contact","link_fd6dc411307f":"/contact"}'::jsonb || coalesce(content->'links','{}'::jsonb)) where slug='irsaliyat' and exists(select 1 from jsonb_object_keys('{"link_e0c7bc0426f0":"/contact","link_fd6dc411307f":"/contact"}'::jsonb) k where not coalesce(content->'links','{}'::jsonb) ? k);

update public.site_pages set content=jsonb_set(content,'{copy}','{"text_e1170ab1997e":{"fr":"Sécurité d''abord","ar":"السلامة أولاً","en":"Safety first"},"text_164066236600":{"fr":"Des véhicules suivis, des chauffeurs formés et des procédures de contrôle à chaque départ.","ar":"مركبات متتبعة، سائقون مؤهلون وإجراءات مراقبة عند كل رحلة.","en":"Tracked vehicles, trained drivers and control procedures at every departure."},"text_a4ed9ff495ee":{"fr":"Proximité","ar":"القرب من الناس","en":"Closeness"},"text_d1e1254035e1":{"fr":"Des équipes locales dans chaque ville, qui connaissent les routes et les attentes des voyageurs.","ar":"فرق محلية في كل مدينة تعرف الطرق وتطلعات المسافرين.","en":"Local teams in every city who know the roads and what travellers need."},"text_1915ad464625":{"fr":"Exigence","ar":"الجودة","en":"Excellence"},"text_fbf2b0944ae5":{"fr":"Une flotte renouvelée, des départs à l''heure et un service client accessible 24/7.","ar":"أسطول متجدد، رحلات في الموعد وخدمة عملاء متاحة 24/7.","en":"A renewed fleet, on-time departures and customer service available 24/7."},"text_652cd9603ac8":{"fr":"Notre histoire","ar":"قصتنا","en":"Our story"},"text_51ef54c529de":{"fr":"Du souk d''Inezgane à un réseau national","ar":"من سوق إنزكان إلى شبكة وطنية","en":"From the Inezgane market to a national network"},"text_26b72d60c687":{"fr":"{{siteName}} a commencé avec une liaison et une idée claire : un transport sûr et régulier au service des gens. Aujourd''hui, la même route continue avec une flotte moderne et une équipe qui connaît le Maroc.","ar":"بدأت {{siteName}} برحلة واحدة ورؤية واضحة: نقل آمن ومنتظم يخدم الناس. اليوم، نواصل نفس الطريق بأسطول حديث وفريق يفهم المغرب.","en":"{{siteName}} began with one route and a clear vision: safe, reliable transport for local people. Today, the same road continues with a modern fleet and a team that knows Morocco."},"text_5a3031c4680d":{"fr":"Fondateur","ar":"المؤسس","en":"Founder"},"text_54b9497e87db":{"fr":"Une vision familiale depuis 1992","ar":"رؤية عائلية منذ 1992","en":"A family vision since 1992"},"text_8c6db3af58e2":{"fr":"L''histoire","ar":"الحكاية","en":"The story"},"text_1148cf3ee1c8":{"fr":"Trente ans sur la même route","ar":"ثلاثون عاماً على نفس الطريق","en":"Thirty years on the same road"},"text_5775e5336150":{"fr":"En 1992, les premières rotations partaient du cœur du souk d''Inezgane pour relier villages et centres urbains du Souss. Les débuts étaient modestes, mais l''engagement était total : respecter les horaires et servir les gens avec honnêteté.","ar":"في 1992، انطلقت أولى الرحلات من قلب سوق إنزكان لربط القرى والحواضر بمنطقة سوس. كانت البداية متواضعة، لكن الالتزام كان كبيراً: احترام المواعيد وخدمة الناس بصدق.","en":"In 1992, the first journeys left the heart of the Inezgane market, connecting villages and towns across the Souss. The start was modest, but the commitment was clear: keep to the schedule and serve people honestly."},"text_6974fce44f26":{"fr":"Au fil des années, le réseau s''est étendu vers le nord et le sud, et Irsaliyat a ajouté le transport de colis sur les mêmes autocars. Aujourd''hui, nous réunissons voyageurs, messagerie express et mobilité d''entreprise.","ar":"مع مرور السنوات، توسعت الشبكة نحو الشمال والجنوب، وانضافت خدمة إرساليات لنقل الأمانات مع نفس الحافلات. اليوم، نجمع بين نقل المسافرين، التوصيل السريع وحلول النقل للشركات.","en":"Over the years the network expanded north and south, and Irsaliyat added parcel transport on the same coaches. Today we bring together passenger travel, express delivery and corporate mobility."},"text_7541c2434aed":{"fr":"Un réseau national","ar":"شبكة وطنية","en":"A national network"},"text_6fae79c72db8":{"fr":"Des équipes locales","ar":"فرق محلية","en":"Local teams"},"text_5852bcae1f62":{"fr":"Une flotte moderne","ar":"أسطول حديث","en":"A modern fleet"},"text_d925c104e333":{"fr":"Un service humain","ar":"خدمة إنسانية","en":"Human service"},"text_09e7d2cf376c":{"fr":"Les étapes","ar":"المراحل","en":"Milestones"},"text_66d2df0e0bda":{"fr":"Les moments qui ont façonné le trajet","ar":"محطات شكلت مسارنا","en":"Moments that shaped the journey"},"text_d0c8a757b7e7":{"fr":"Aucune étape publiée","ar":"لا توجد مراحل منشورة","en":"No milestones yet"},"text_49f6c0ea2f85":{"fr":"Contactez-nous pour en savoir plus sur SLKM.","ar":"تواصلوا معنا لمعرفة المزيد عن SLKM.","en":"Contact us to learn more about SLKM."},"text_c3201fad6f90":{"fr":"Nos valeurs","ar":"قيمنا","en":"Our values"},"text_fb69107a96df":{"fr":"Ce qui ne change pas","ar":"ما لا يتغير مع مرور السنوات","en":"What never changes"},"text_d95a1270801d":{"fr":"Présence","ar":"الحضور","en":"Presence"},"text_17c70e1250fa":{"fr":"Notre réseau sur la carte","ar":"شبكتنا على الخريطة","en":"Our network on the map"},"text_b140ab9fb32c":{"fr":"{{agencies.length}} agences actives relient le nord, le centre et le sud.","ar":"{{agencies.length}} وكالة نشطة تربط الشمال والوسط والجنوب.","en":"{{agencies.length}} active agencies connecting north, centre and south."},"text_f139c54b7dd6":{"fr":"Toutes les agences","ar":"كل الوكالات","en":"All agencies"},"text_9f38ae8098e2":{"fr":"Nous contacter","ar":"تواصل معنا","en":"Contact us"},"text_cc48426bf7db":{"fr":"Rejoignez le voyage","ar":"انضموا إلى رحلتنا","en":"Join the journey"},"text_fda674ddaf45":{"fr":"Que vous voyagiez ou travailliez avec nous, bienvenue","ar":"سواء كنتم مسافراً أو شريكاً، مرحباً بكم","en":"Whether you travel or partner with us, welcome"},"text_ffcadf5671ac":{"fr":"Découvrez nos lignes ou demandez une offre adaptée à vos équipes.","ar":"استكشفوا خطوطنا أو اطلبوا عرضاً مخصصاً لفريقكم.","en":"Explore our routes or request a tailored offer for your team."},"text_567565cc67ca":{"fr":"Les lignes","ar":"الخطوط","en":"Routes"},"text_330a53f83685":{"fr":"Un devis","ar":"عرض أسعار","en":"Get a quote"}}'::jsonb || coalesce(content->'copy','{}'::jsonb)) where slug='about' and exists(select 1 from jsonb_object_keys('{"text_e1170ab1997e":{"fr":"Sécurité d''abord","ar":"السلامة أولاً","en":"Safety firs