48cf3ee1c8":{"fr":"Trente ans sur la même route","ar":"ثلاثون عاماً على نفس الطريق","en":"Thirty years on the same road"},"text_5775e5336150":{"fr":"En 1992, les premières rotations partaient du cœur du souk d''Inezgane pour relier villages et centres urbains du Souss. Les débuts étaient modestes, mais l''engagement était total : respecter les horaires et servir les gens avec honnêteté.","ar":"في 1992، انطلقت أولى الرحلات من قلب سوق إنزكان لربط القرى والحواضر بمنطقة سوس. كانت البداية متواضعة، لكن الالتزام كان كبيراً: احترام المواعيد وخدمة الناس بصدق.","en":"In 1992, the first journeys left the heart of the Inezgane market, connecting villages and towns across the Souss. The start was modest, but the commitment was clear: keep to the schedule and serve people honestly."},"text_6974fce44f26":{"fr":"Au fil des années, le réseau s''est étendu vers le nord et le sud, et Irsaliyat a ajouté le transport de colis sur les mêmes autocars. Aujourd''hui, nous réunissons voyageurs, messagerie express et mobilité d''entreprise.","ar":"مع مرور السنوات، توسعت الشبكة نحو الشمال والجنوب، وانضافت خدمة إرساليات لنقل الأمانات مع نفس الحافلات. اليوم، نجمع بين نقل المسافرين، التوصيل السريع وحلول النقل للشركات.","en":"Over the years the network expanded north and south, and Irsaliyat added parcel transport on the same coaches. Today we bring together passenger travel, express delivery and corporate mobility."},"text_7541c2434aed":{"fr":"Un réseau national","ar":"شبكة وطنية","en":"A national network"},"text_6fae79c72db8":{"fr":"Des équipes locales","ar":"فرق محلية","en":"Local teams"},"text_5852bcae1f62":{"fr":"Une flotte moderne","ar":"أسطول حديث","en":"A modern fleet"},"text_d925c104e333":{"fr":"Un service humain","ar":"خدمة إنسانية","en":"Human service"},"text_09e7d2cf376c":{"fr":"Les étapes","ar":"المراحل","en":"Milestones"},"text_66d2df0e0bda":{"fr":"Les moments qui ont façonné le trajet","ar":"محطات شكلت مسارنا","en":"Moments that shaped the journey"},"text_d0c8a757b7e7":{"fr":"Aucune étape publiée","ar":"لا توجد مراحل منشورة","en":"No milestones yet"},"text_49f6c0ea2f85":{"fr":"Contactez-nous pour en savoir plus sur SLKM.","ar":"تواصلوا معنا لمعرفة المزيد عن SLKM.","en":"Contact us to learn more about SLKM."},"text_c3201fad6f90":{"fr":"Nos valeurs","ar":"قيمنا","en":"Our values"},"text_fb69107a96df":{"fr":"Ce qui ne change pas","ar":"ما لا يتغير مع مرور السنوات","en":"What never changes"},"text_d95a1270801d":{"fr":"Présence","ar":"الحضور","en":"Presence"},"text_17c70e1250fa":{"fr":"Notre réseau sur la carte","ar":"شبكتنا على الخريطة","en":"Our network on the map"},"text_b140ab9fb32c":{"fr":"{{agencies.length}} agences actives relient le nord, le centre et le sud.","ar":"{{agencies.length}} وكالة نشطة تربط الشمال والوسط والجنوب.","en":"{{agencies.length}} active agencies connecting north, centre and south."},"text_f139c54b7dd6":{"fr":"Toutes les agences","ar":"كل الوكالات","en":"All agencies"},"text_9f38ae8098e2":{"fr":"Nous contacter","ar":"تواصل معنا","en":"Contact us"},"text_cc48426bf7db":{"fr":"Rejoignez le voyage","ar":"انضموا إلى رحلتنا","en":"Join the journey"},"text_fda674ddaf45":{"fr":"Que vous voyagiez ou travailliez avec nous, bienvenue","ar":"سواء كنتم مسافراً أو شريكاً، مرحباً بكم","en":"Whether you travel or partner with us, welcome"},"text_ffcadf5671ac":{"fr":"Découvrez nos lignes ou demandez une offre adaptée à vos équipes.","ar":"استكشفوا خطوطنا أو اطلبوا عرضاً مخصصاً لفريقكم.","en":"Explore our routes or request a tailored offer for your team."},"text_567565cc67ca":{"fr":"Les lignes","ar":"الخطوط","en":"Routes"},"text_330a53f83685":{"fr":"Un devis","ar":"عرض أسعار","en":"Get a quote"}}'::jsonb) k where not coalesce(content->'copy','{}'::jsonb) ? k);
update public.site_pages set content=jsonb_set(content,'{links}','{"link_3bd6b58d0eb5":"/lignes","link_72a342010d62":"/contact","link_a6d076cfdd50":"/lignes","link_4e08d4e7785a":"/services"}'::jsonb || coalesce(content->'links','{}'::jsonb)) where slug='about' and exists(select 1 from jsonb_object_keys('{"link_3bd6b58d0eb5":"/lignes","link_72a342010d62":"/contact","link_a6d076cfdd50":"/lignes","link_4e08d4e7785a":"/services"}'::jsonb) k where not coalesce(content->'links','{}'::jsonb) ? k);

update public.site_pages set content=jsonb_set(content,'{copy}','{"text_1e013606c03c":{"fr":"Solutions entreprises","ar":"حلول الشركات","en":"Business solutions"},"text_fd23bd01afda":{"fr":"Ensemble, allez plus loin","ar":"معاً، إلى أبعد مدى","en":"Move further, together"},"text_7e9f0fa7d11a":{"fr":"Des solutions de transport sur mesure pour entreprises et institutions : personnel, tourisme et scolaire, avec suivi et coordination.","ar":"حلول نقل مخصصة للشركات والمؤسسات: نقل الموظفين، رحلات سياحية ورحلات مدرسية، مع تتبع وتنسيق.","en":"Tailored transport for companies and institutions: staff mobility, tourism and school trips, with tracking and coordination."},"text_3767bd206863":{"fr":"Demander un devis","ar":"طلب عرض أسعار","en":"Request a quote"},"text_88a1b6779e84":{"fr":"Nos offres","ar":"عروضنا","en":"Our offers"},"text_4a8d041ca795":{"fr":"Une solution de mobilité pour chaque besoin","ar":"حل نقل يناسب كل احتياج","en":"A mobility solution for every need"},"text_ef40bc4e956d":{"fr":"Chaque proposition est construite selon le nombre de passagers, la distance, la fréquence et le niveau de service.","ar":"نصمم كل عرض حسب عدد المسافرين، المسافة، التردد ومستوى الخدمة المطلوب.","en":"Every proposal is built around passenger count, distance, frequency and service level."},"text_a9c1e59fe075":{"fr":"Pourquoi SLKM","ar":"لماذا إس إل كي إم","en":"Why SLKM"},"text_7ad3d45349f8":{"fr":"Un partenaire transport que vos équipes connaissent","ar":"شريك نقل تعرفه الفرق","en":"A transport partner your teams can rely on"},"text_81208c8b4684":{"fr":"Trente ans d''expérience terrain, une flotte diversifiée et une équipe de coordination unique pour chaque détail.","ar":"ثلاثون عاماً من الخبرة الميدانية، أسطول متنوع وفريق تنسيق واحد يجمع كل التفاصيل.","en":"Thirty years of field experience, a diversified fleet and one coordination team for every detail."},"text_890e612f8d9b":{"fr":"Ponctualité suivie","ar":"التزام بالمواعيد","en":"Tracked punctuality"},"text_39291fb20b35":{"fr":"Sécurité & assurance","ar":"السلامة والتأمين","en":"Safety & insurance"},"text_7f144d54c07f":{"fr":"Chauffeurs formés","ar":"سائقون مؤهلون","en":"Trained drivers"},"text_7cbe7e5a7bf9":{"fr":"Facturation entreprise","ar":"فواتير للشركات","en":"Corporate invoicing"},"text_e0122aab53de":{"fr":"Flotte récente","ar":"أسطول حديث","en":"Modern fleet"},"text_118661e672de":{"fr":"Des autocars équipés pour la route et le quotidien","ar":"حافلات مجهزة للرحلات الطويلة واليومية","en":"Coaches equipped for long-distance and daily duty"},"text_f5554ae2f6b7":{"fr":"Équipe B2B","ar":"فريق الشركات","en":"B2B desk"},"text_81cced723304":{"fr":"Réponse sous 24 heures","ar":"نتواصل معكم خلال 24 ساعة","en":"We reply within 24 hours"},"text_52afccc9bd18":{"fr":"Institutions","ar":"للمؤسسات","en":"For institutions"},"text_4844600a506a":{"fr":"Contrats annuels, suivi des trajets et facturation mensuelle structurée.","ar":"عقود سنوية، تتبع الرحلات وفواتير شهرية منظمة.","en":"Annual contracts, journey tracking and structured monthly invoicing."},"text_2456f711edaf":{"fr":"Une mobilité adaptée à vos équipes","ar":"حلول تنقل مصممة لشركتكم","en":"Mobility built around your team"},"text_4b000c1c5bff":{"fr":"Entreprise","ar":"اسم الشركة","en":"Company"},"text_2b5c3d26721a":{"fr":"Contact","ar":"الشخص المسؤول","en":"Contact person"},"text_cc4c424b571f":{"fr":"Téléphone","ar":"الهاتف","en":"Phone"},"text_2550d962e536":{"fr":"E-mail","ar":"البريد الإلكتروني","en":"Email"},"text_da26234dc917":{"fr":"Passagers","ar":"عدد المسافرين","en":"Passengers"},"text_0bc226ec29cd":{"fr":"Ville de départ","ar":"مدينة الانطلاق","en":"Origin city"},"text_88aaac5494d3":{"fr":"Ville d''arrivée","ar":"مدينة الوصول","en":"Destination"},"text_13f85bc0d96a":{"fr":"Type de service","ar":"نوع الخدمة","en":"Service type"},"text_e6d84389cc74":{"fr":"Transport du personnel","ar":"نقل الموظفين","en":"Staff transport"},"text_9b0c6974de4d":{"fr":"Voyages touristiques","ar":"رحلات سياحية","en":"Tourism trips"},"text_0aa120a657ef":{"fr"