update public.site_pages set content=jsonb_set(content,'{copy}','{"text_1a04b59df37a":{"fr":"Bonjour, j''ai besoin d''aide.","ar":"مرحباً، أحتاج مساعدة.","en":"Hello, I need help."},"text_cc4c424b571f":{"fr":"Téléphone","ar":"الهاتف","en":"Phone"},"text_2550d962e536":{"fr":"E-mail","ar":"البريد الإلكتروني","en":"Email"},"text_79e5cf20de0b":{"fr":"Adresse","ar":"العنوان","en":"Address"},"text_2b5c3d26721a":{"fr":"Contact","ar":"اتصل بنا","en":"Contact"},"text_ed0d4f31b3c0":{"fr":"Nous sommes là pour répondre à vos questions","ar":"نحن هنا للإجابة على أسئلتكم","en":"We are here to answer your questions"},"text_99352e031027":{"fr":"Réservation, suivi de colis, devis entreprise ou assistance urgente : choisissez le canal qui vous convient.","ar":"حجز، تتبع أمانة، عرض أسعار للشركات أو مساعدة عاجلة: اختاروا القناة التي تناسبكم.","en":"Booking, parcel tracking, a corporate quote or urgent help: choose the channel that suits you."},"text_a9b01b010447":{"fr":"Canaux de contact","ar":"قنوات الاتصال","en":"Contact channels"},"text_2f4647667d91":{"fr":"Les coordonnées sont momentanément indisponibles. Utilisez le formulaire pour nous écrire.","ar":"بيانات الاتصال غير متاحة حالياً. يمكنكم استخدام النموذج لمراسلتنا.","en":"Contact details are currently unavailable. You can use the form to message us."},"text_cdcbda2a3dd2":{"fr":"Lignes d''assistance","ar":"خطوط المساعدة","en":"Support lines"},"text_c474fa194117":{"fr":"Écrivez-nous via le formulaire pour préparer votre voyage.","ar":"تواصلوا معنا عبر النموذج لتحضير رحلتكم.","en":"Use the form to contact us about your journey."},"text_f31f4fc85132":{"fr":"Localisation","ar":"الموقع","en":"Location"},"text_96ac3a928459":{"fr":"Trouvez l''agence la plus proche","ar":"اعثروا على أقرب وكالة","en":"Find your nearest agency"},"text_6aa115334159":{"fr":"Cliquez sur une épingle pour l''adresse et le téléphone, ou utilisez la page des lignes pour filtrer les trajets.","ar":"انقروا على أي نقطة للاطلاع على العنوان والهاتف، أو استعملوا صفحة الخطوط لتصفية الرحلات.","en":"Click a pin for the address and phone, or use the routes page to filter journeys."},"text_a44e9e92caa9":{"fr":"Écrivez-nous","ar":"أرسل لنا رسالة","en":"Send us a message"},"text_c0ab5dbad189":{"fr":"Nous répondons sous un jour ouvré.","ar":"سنعود إليكم خلال يوم عمل واحد.","en":"We reply within one business day."},"text_c8af6e29fba8":{"fr":"Nom complet","ar":"الاسم الكامل","en":"Full name"},"text_db59ebb27218":{"fr":"Sujet","ar":"الموضوع","en":"Subject"},"text_2f77668a9dfb":{"fr":"Message","ar":"الرسالة","en":"Message"},"text_b5875ab3a419":{"fr":"Vos données ne sont jamais revendues.","ar":"لن نشارك بياناتكم مع أي طرف ثالث.","en":"We never share your details with third parties."},"text_bf2f14e82f15":{"fr":"Envoi...","ar":"جارٍ الإرسال...","en":"Sending..."},"text_79075209f2bb":{"fr":"Envoyer","ar":"إرسال","en":"Send"}}'::jsonb || coalesce(content->'copy','{}'::jsonb)) where slug='contact' and exists(select 1 from jsonb_object_keys('{"text_1a04b59df37a":{"fr":"Bonjour, j''ai besoin d''aide.","ar":"مرحباً، أحتاج مساعدة.","en":"Hello, I need help."},"text_cc4c424b571f":{"fr":"Téléphone","ar":"الهاتف","en":"Phone"},"text_2550d962e536":{"fr":"E-mail","ar":"البريد الإلكتروني","en":"Email"},"text_79e5cf20de0b":{"fr":"Adresse","ar":"العنوان","en":"Address"},"text_2b5c3d26721a":{"fr":"Contact","ar":"اتصل بنا","en":"Contact"},"text_ed0d4f31b3c0":{"fr":"Nous sommes là pour répondre à vos questions","ar":"نحن هنا للإجابة على أسئلتكم","en":"We are here to answer your questions"},"text_99352e031027":{"fr":"Réservation, suivi de colis, devis entreprise ou assistance urgente : choisissez le canal qui vous convient.","ar":"حجز، تتبع أمانة، عرض أسعار للشركات أو مساعدة عاجلة: اختاروا القناة التي تناسبكم.","en":"Booking, parcel tracking, a corporate quote or urgent help: choose the channel that suits you."},"text_a9b01b010447":{"fr":"Canaux de contact","ar":"قنوات الاتصال","en":"Contact channels"},"text_2f4647667d91":{"fr":"Les coordonnées sont momentanément indisponibles. Utilisez le formulaire pour nous écrire.","ar":"بيانات الاتصال غير متاحة حالياً. يمكنكم استخدام النموذج لمراسلتنا.","en":"Contact details are currently unavailable. You can use the form to message us."},"text_cdcbda2a3dd2":{"fr":"Lignes d''assistance","ar":"خطوط المساعدة","en":"Support lines"},"text_c474fa194117":{"fr":"Écrivez-nous via le formulaire pour préparer votre voyage.","ar":"تواصلوا معنا عبر النموذج لتحضير رحلتكم.","en":"Use the form to contact us about your journey."},"text_f31f4fc85132":{"fr":"Localisation","ar":"الموقع","en":"Location"},"text_96ac3a928459":{"fr":"Trouvez l''agence la plus proche","ar":"اعثروا على أقرب وكالة","en":"Find your nearest agency"},"text_6aa115334159":{"fr":"Cliquez sur une épingle pour l''adresse et le téléphone, ou utilisez la page des lignes pour filtrer les trajets.","ar":"انقروا على أي نقطة للاطلاع على العنوان والهاتف، أو استعملوا صفحة الخطوط لتصفية الرحلات.","en":"Click a pin for the address and phone, or use the routes page to filter journeys."},"text_a44e9e92caa9":{"fr":"Écrivez-nous","ar":"أرسل لنا رسالة","en":"Send us a message"},"text_c0ab5dbad189":{"fr":"Nous répondons sous un jour ouvré.","ar":"سنعود إليكم خلال يوم عمل واحد.","en":"We reply within one business day."},"text_c8af6e29fba8":{"fr":"Nom complet","ar":"الاسم الكامل","en":"Full name"},"text_db59ebb27218":{"fr":"Sujet","ar":"الموضوع","en":"Subject"},"text_2f77668a9dfb":{"fr":"Message","ar":"الرسالة","en":"Message"},"text_b5875ab3a419":{"fr":"Vos données ne sont jamais revendues.","ar":"لن نشارك بياناتكم مع أي طرف ثالث.","en":"We never share your details with third parties."},"text_bf2f14e82f15":{"fr":"Envoi...","ar":"جارٍ الإرسال...","en":"Sending..."},"text_79075209f2bb":{"fr":"Envoyer","ar":"إرسال","en":"Send"}}'::jsonb) k where not coalesce(content->'copy','{}'::jsonb) ? k);
