update public.site_pages set content=jsonb_set(content,'{copy}','{"text_1831f60fe790":{"fr":"Le journal","ar":"المدونة","en":"Journal"},"text_175c55873466":{"fr":"Actualités, conseils et destinations","ar":"أخبار، نصائح ووجهات","en":"News, advice and destinations"},"text_bd64b55010c7":{"fr":"Des nouvelles utiles sur nos lignes, Irsaliyat et des conseils pour préparer votre prochain voyage.","ar":"معلومات عملية عن خطوطنا، خدمة إرساليات، ونصائح لتحضير رحلتكم القادمة.","en":"Practical updates on our routes, Irsaliyat and advice to plan your next journey."},"text_bee9f69397b0":{"fr":"À la une","ar":"مقال مميز","en":"Featured"},"text_e36036739f5c":{"fr":"Le choix de la rédaction","ar":"اختيار المحرر","en":"Editor''s pick"},"text_4ef07352550e":{"fr":"Tous les articles","ar":"كل المقالات","en":"All articles"},"text_6f0b048748bb":{"fr":"Suivez la vie du réseau","ar":"تابعوا أخبار الشبكة","en":"Follow network updates"},"text_6acd985680f8":{"fr":"Pages des articles","ar":"صفحات المقالات","en":"Article pages"},"text_6c857416ce4b":{"fr":"Aucun article publié","ar":"لا توجد مقالات منشورة","en":"No published articles"},"text_440bf68b4bef":{"fr":"Découvrez nos lignes et nos services en attendant nos prochaines nouvelles.","ar":"اكتشفوا خطوطنا وخدماتنا أثناء انتظار أخبارنا القادمة.","en":"Explore our routes and services while you wait for our next update."},"text_c37f1459c181":{"fr":"Explorer les lignes","ar":"استكشفوا الخطوط","en":"Explore routes"}}'::jsonb || coalesce(content->'copy','{}'::jsonb)) where slug='blog' and exists(select 1 from jsonb_object_keys('{"text_1831f60fe790":{"fr":"Le journal","ar":"المدونة","en":"Journal"},"text_175c55873466":{"fr":"Actualités, conseils et destinations","ar":"أخبار، نصائح ووجهات","en":"News, advice and destinations"},"text_bd64b55010c7":{"fr":"Des nouvelles utiles sur nos lignes, Irsaliyat et des conseils pour préparer votre prochain voyage.","ar":"معلومات عملية عن خطوطنا، خدمة إرساليات، ونصائح لتحضير رحلتكم القادمة.","en":"Practical updates